/**
 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
 * plus any control-panel/app install script and selected add-ons. Long installs
 * run in the background so the VM reports ready promptly.
 */
/**
 * The nxeon-shipper install: fetch the static binary, drop its config (server
 * id + per-server token minted by the caller, see provision()), install the
 * systemd unit, and start it. Idempotent (safe to re-run on a retried
 * provision) and — like the Claude CLI install — backgrounded via the outer
 * nohup so a slow/blocked download never delays the VM reporting ready.
 *
 * `curl -fsSL … | sh`-style external installs are the established convention
 * here (see get.docker.com / claude.ai/install.sh above); this one pulls from
 * our own APP_URL instead of a third party since the binary is ours.
 */
function shipperInstallScript(serverId: string, token: string, nodeKind: "VPS" | "GAME"): string {
  const appUrl = process.env.APP_URL ?? "https://nxeon.cloud";
  const config = JSON.stringify({
    server_id: serverId,
    token,
    ingest_url: `${appUrl}/api/telemetry/ingest`,
    node_kind: nodeKind,
  });
  return [
    "mkdir -p /etc/nxeon",
    `cat > /etc/nxeon/shipper.json <<'NXTJSON'\n${config}\nNXTJSON`,
    "chmod 600 /etc/nxeon/shipper.json",
    `curl -fsSL "${appUrl}/dl/nxeon-shipper-linux-amd64" -o /usr/local/bin/nxeon-shipper.tmp && ` +
      "chmod +x /usr/local/bin/nxeon-shipper.tmp && mv /usr/local/bin/nxeon-shipper.tmp /usr/local/bin/nxeon-shipper",
    `curl -fsSL "${appUrl}/dl/nxeon-shipper.service" -o /etc/systemd/system/nxeon-shipper.service`,
    "systemctl daemon-reload && systemctl enable --now nxeon-shipper",
  ].join("\n");
}

function buildCloudInit(server: any, opts: { golden?: boolean } = {}): string {
  const addons = (server.addons ?? {}) as {
    malwareScanner?: boolean;
    dailyBackup?: boolean;
    docker?: boolean;
    claudeCode?: boolean;
  };
  const setup: string[] = [];

  // Translates the customer's checkout-time variant/config choices, applies
  // per-server secrets (including DayZ's shared Steam credential and Arma
  // Reforger's admin password), and wraps the whole thing in a systemd unit
  // so the game control panel can see/manage it — see buildGameSetupScript's
  // own comment (worker/game-variant.ts). No-op (returns null) for a
  // non-game template. Also reused by gameReinstall (worker/game-control.ts)
  // so a wipe+reinstall rebuilds the identical script, secrets included.
  //
  // ORDER (2026-10-01): the game goes FIRST. PROVISION does not finish until
  // the game's port opens, and everything before it in this script is on that
  // critical path — the Claude CLI install used to run first and cost every
  // game order ~10s (measured) before Docker even started. Claude Code is a
  // convenience for VPS customers; on a game server it can finish afterwards.
  const gameSetup = buildGameSetupScript(server);
  if (gameSetup) setup.push(gameSetup);

  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
  // out. Customers SSH in and run `claude` using their own subscription or API
  // key — no setup on our side, zero token cost to us. Installs run in the
  // background (nohup below) so the VM still reports ready quickly.
  if (addons.claudeCode !== false) {
    // Same steps the backfill (task #73) runs on existing servers — one source of
    // truth in lib/claude-install.ts, so cloud-init and backfill never drift.
    setup.push(...CLAUDE_CLI_INSTALL_STEPS);
  }

  if (addons.docker) setup.push("{ command -v docker >/dev/null 2>&1 || curl -fsSL https://get.docker.com | sh; } && systemctl enable --now docker");
  if (addons.malwareScanner)
    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
  // NxCloud: when this VM backs a managed Nextcloud instance, `provision` stashes
  // the per-instance install script here (admin creds injected). See worker/nxcloud.ts.
  if (server.__nxcloudSetup) setup.push(server.__nxcloudSetup);

  // Live telemetry (see agent/nxeon-shipper + lib/telemetry-token.ts): `provision`
  // mints a per-server token and stashes it here, same convention as
  // __nxcloudSetup above, right before calling buildCloudInit(). Every VPS/game
  // server gets the shipper — there's no opt-out addon toggle for this one since
  // it's operational telemetry, not a customer-facing feature.
  if (server.__telemetryToken) {
    const kind: "VPS" | "GAME" = server.gamePlanId ? "GAME" : "VPS";
    setup.push(shipperInstallScript(server.id, server.__telemetryToken, kind));
  }

  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");

  // Every VM gets a swapfile. A small plan (the 2 GB Starter is the common one)
  // with ZERO swap OOM-kills under any spike — a container image build, a traffic
  // burst, a migrated app's first request — and the kernel kills a process with no
  // warning and nothing to fall back on. A RAM-sized swapfile (capped so it never
  // eats a small root disk) turns a hard kill into slow-but-alive. Idempotent:
  // skips if any swap is already on or /swapfile already exists.
  const swapScript = [
    "#!/bin/bash",
    "# Nxeon: ensure a swapfile exists as an OOM safety net on small-RAM VMs.",
    "if swapon --show=NAME --noheadings 2>/dev/null | grep -q .; then exit 0; fi",
    "[ -e /swapfile ] && exit 0",
    'MEM_MB=$(awk "/MemTotal/{print int(\\$2/1024)}" /proc/meminfo 2>/dev/null || echo 1024)',
    "SWAP_MB=$MEM_MB",
    '[ "$SWAP_MB" -lt 1024 ] && SWAP_MB=1024',
    '[ "$SWAP_MB" -gt 4096 ] && SWAP_MB=4096',
    "# Leave >2 GB free on / so the swapfile never fills the root disk.",
    'AVAIL_MB=$(df -Pm / | awk "NR==2{print \\$4}")',
    '[ -n "$AVAIL_MB" ] && [ "$AVAIL_MB" -lt $((SWAP_MB + 2048)) ] && SWAP_MB=$((AVAIL_MB - 2048))',
    '[ "$SWAP_MB" -lt 256 ] && exit 0',
    "fallocate -l ${SWAP_MB}M /swapfile 2>/dev/null || dd if=/dev/zero of=/swapfile bs=1M count=${SWAP_MB} 2>/dev/null || exit 0",
    "chmod 600 /swapfile",
    "mkswap /swapfile >/dev/null 2>&1 || exit 0",
    "swapon /swapfile 2>/dev/null || exit 0",
    "grep -q '^/swapfile ' /etc/fstab 2>/dev/null || echo '/swapfile none swap sw 0 0' >> /etc/fstab",
    "grep -q '^vm.swappiness' /etc/sysctl.conf 2>/dev/null || { echo 'vm.swappiness=10' >> /etc/sysctl.conf; sysctl -w vm.swappiness=10 >/dev/null 2>&1 || true; }",
  ].join("\n");

  // A friendly first-login guide + MOTD banner pointing at the portal hub.
  const welcome = [
    "# Welcome to your Nxeon server",
    "",
    "## Build anything with Claude Code — it's already installed",
    "",
    "1. You're already logged in. Just run:",
    "",
    "   claude",
    "",
    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
    "   Anthropic API key. See the step-by-step guide with screenshots at:",
    "",
    "   https://nxeon.cloud/dashboard/claude-code",
    "",
    "3. Then describe what you want in plain English, for example:",
    '   "Build a modern website for my coffee shop with a menu and contact form,',
    '    then run it and tell me the URL to preview it."',
    "",
    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
    "and 20+ more) and how-to guides live in your portal at the link above.",
    "",
    "Happy building!",
  ].join("\n");

  // Honest MOTD: check for the binary at login and only claim it's installed when
  // it really is. A failed background install must never greet the customer with
  // "Claude Code is pre-installed" and then 'command not found' — it tells them how
  // to install it instead.
  const motd = [
    "#!/bin/sh",
    'if [ -t 1 ]; then',
    '  if command -v claude >/dev/null 2>&1 || [ -x /usr/local/bin/claude ]; then',
    '    printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
    '    printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
    "  else",
    '    printf "\\n  \\033[1mNxeon\\033[0m — install Claude Code:  curl -fsSL https://claude.ai/install.sh | bash\\n"',
    '    printf "  Then run \\033[1mclaude\\033[0m. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
    "  fi",
    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
    "fi",
  ].join("\n");

  // Package block: see cloudInitPackagesBlock (worker/cloud-init-parts.ts) —
  // omitted entirely on a golden template, where the packages are baked in and
  // the apt update alone was ~70s of every first boot.
  return `#cloud-config
${cloudInitPackagesBlock(!!opts.golden)}ssh_pwauth: true
disable_root: false
write_files:
  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
    permissions: "0644"
    content: |
      PermitRootLogin yes
      PasswordAuthentication yes
  - path: /root/START-WITH-CLAUDE.md
    permissions: "0644"
    content: |
${indentBlock(welcome, 6)}
  - path: /etc/profile.d/nxeon-welcome.sh
    permissions: "0755"
    content: |
${indentBlock(motd, 6)}
  - path: /root/nxeon-swap.sh
    permissions: "0755"
    content: |
${indentBlock(swapScript, 6)}
  - path: /root/nxeon-setup.sh
    permissions: "0755"
    content: |
${indentBlock(script, 6)}
runcmd:
  - systemctl enable --now qemu-guest-agent
  - systemctl restart ssh || systemctl restart sshd
  - /root/nxeon-swap.sh > /var/log/nxeon-swap.log 2>&1 || true
${SETUP_RUNCMD}
`;
}

const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";

/**
 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
 *
 * If the archive listing cannot be read we do NOT silently fall back to the raw
 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
 * and a provision that fails is recoverable while a cross-tenant disclosure is
 * not. The job retries; an operator sees why.
 */
/**
 * Atomically claim the next never-before-used vmid floor (Setting
 * `vmid_high_water`), so two concurrent PROVISIONs (WORKER_CONCURRENCY > 1)
 * never start probing from the same id, and an id is never handed out twice
 * even after its server row is deleted. One SQL statement: insert-or-bump.
 */
async function claimVmidFloor(floor: number): Promise<number> {
  // Shared with the VM move engine (lib/vmid-high-water.ts) so a move's target
  // vmid and a provision's new vmid can never be the same number.
  return claimVmidHighWater(floor);
}

/**
 * Side-effect-free pieces of the per-server cloud-init vendor snippet built by
 * `buildCloudInit` (worker/index.ts). Kept here so they can be unit tested —
 * importing worker/index.ts starts the job loop.
 */

/**
 * Packages every VM needs before anything else in the snippet works:
 *   - qemu-guest-agent: provision()'s boot check and every QGA-based feature
 *     (password reset, in-guest disk/memory samples, restore password resync).
 *   - unzip: found live 2026-09-09 — worker/game-mods.ts's zip-type mod
 *     install has always assumed it exists on every game VM, but nothing ever
 *     installed it. Universal (not game-conditional): trivial and useful on a
 *     plain VPS too.
 *
 * On a STOCK cloud image this block stays exactly as it always was. On a
 * GOLDEN template (scripts/golden/build-golden-template.sh) both are already
 * installed, and `package_update: true` alone was the single biggest slice of
 * first boot — measured 2026-10-01 on a stock Ubuntu 24.04 clone:
 * `config-package_update_upgrade_install ran successfully and took 72.150
 * seconds`, i.e. the guest agent could not answer until ~95s after start. So a
 * golden clone emits nothing here.
 *
 * Returns either "" or a block ending in a newline, so the caller can splice
 * it directly in front of the next top-level key.
 */
export function cloudInitPackagesBlock(golden: boolean): string {
  if (golden) return "";
  return ["package_update: true", "packages:", "  - qemu-guest-agent", "  - unzip", ""].join("\n");
}

/**
 * The runcmd line that launches /root/nxeon-setup.sh in the background.
 *
 * The setup script runs under `set -x`, so its log holds every command it
 * ran — including per-server secrets substituted into `docker create -e
 * ADMIN_PASSWORD=…` and the telemetry token. That log used to be created by a
 * plain `>` redirect, i.e. with the default umask: 0644, readable by every
 * local account on the customer's VM (www-data, a database user, a
 * compromised app). Pre-create it 0600 and append to it instead.
 */
/*
 * 2026-10-02: launched as its OWN transient systemd unit (`nxeon-setup.service`)
 * rather than a bare `nohup … &` child of cloud-init. A background child lives
 * in cloud-init's cgroup and is at the mercy of how that unit is stopped
 * (cloud-init's newer single-process mode, a `systemctl restart cloud-final`,
 * any KillMode change); its own unit also gives the platform `systemctl status
 * nxeon-setup` + the journal. Falls back to the old nohup when systemd-run is
 * missing (non-systemd image), so nothing that worked before stops working.
 * The worker never relies on this run finishing: it polls
 * /var/lib/nxeon/game-setup.state and re-launches the idempotent game setup
 * itself when needed (worker/provision-guest.ts).
 */
export const SETUP_RUNCMD = [
  "  - install -m 600 /dev/null /var/log/nxeon-setup.log",
  "  - systemd-run --unit=nxeon-setup --collect --no-block /bin/bash -c '/root/nxeon-setup.sh >> /var/log/nxeon-setup.log 2>&1' || nohup /root/nxeon-setup.sh >> /var/log/nxeon-setup.log 2>&1 &",
].join("\n");

// READ-ONLY helper: run a shell script file on a server's VM by hostname. Usage: tsx host-run.ts <hostname> <script.sh>
import { db } from "@/lib/db";
import { withServerSsh, exec } from "@/lib/ssh-exec";
import fs from "node:fs";
(async () => {
  const s: any = await db.server.findFirst({ where: { hostname: process.argv[2] }, include: { node: true, dedicatedIp: true, portForwards: true } });
  if (!s) throw new Error("no such server");
  const b64 = fs.readFileSync(process.argv[3]).toString("base64");
  const r = await withServerSsh(s, (c) => exec(c, `echo ${b64} | base64 -d | bash 2>&1`, 120000));
  console.log(r.stdout, r.stderr.slice(0, 200));
  process.exit(0);
})().catch((e) => { console.error("FATAL", String(e.message).slice(-250)); process.exit(1); });

/**
 * Inject `-e TYPE=<VARIANT>` into a Minecraft OsTemplate's setupScript from
 * `Server.gameVariant` (the customer's checkout choice — vanilla/paper/purpur/
 * fabric/forge, see lib/game-config.ts's MINECRAFT.variants).
 *
 * Found live 2026-08-30: this substitution never existed anywhere in the
 * provisioning pipeline. The OsTemplate's setupScript is one static string
 * with no `TYPE` at all, so `gameVariant` was captured at checkout, stored on
 * `Server`, and then completely ignored — every Minecraft customer got plain
 * Vanilla regardless of what they picked (or paid for a plugin-support tier
 * and had their manually-installed plugins never load, since Vanilla has no
 * plugin API at all). Diagnosed via a real customer ticket: the fix here is
 * minecraft-specific by design (it's the only family with a real variant
 * concept today) — generalize via `schemaFor(family)` if another family gains
 * one, rather than hardcoding a second family name here.
 *
 * Explicit and idempotent: always injects a `TYPE`, even for "vanilla" —
 * removes any reliance on the image's own default ever staying Vanilla — and
 * is a no-op if the script already names an explicit `TYPE` (never override
 * something a future per-family script sets on purpose).
 *
 * Kept in its own side-effect-free module (rather than inline in
 * worker/index.ts) so it can be unit tested directly — importing
 * worker/index.ts runs its top-level `main()` job-polling loop.
 */
import { randomBytes, createHash } from "node:crypto";
import { schemaFor, minecraftImageForVersion } from "../lib/game-config";
import { isGameFamily, controlSpec, isSafeRemotePath } from "../lib/game-control";
import { dayzSteamCredentials } from "../lib/dayz-steam";
import { applyPinToSetupScript, type PinPlan } from "../lib/mcjars/pin";
import { applyFivemSetup } from "../lib/fivem-install";
import { fivemLicenseKey, deriveFivemSecrets } from "../lib/fivem-license";

function generatePassword(): string {
  // URL-safe, no ambiguous chars, 16 chars — same shape as worker/index.ts's
  // own generatePassword (kept as a small local copy rather than a shared
  // util, matching this codebase's existing convention — see also
  // worker/nxcloud.ts and lib/actions-company-mail.ts).
  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
}

/**
 * Rust: the `oxide` server type turns on the Oxide framework that
 * didstopia/rust-server ships (RUST_OXIDE_ENABLED=1; it downloads Oxide on
 * boot and keeps it current with RUST_OXIDE_UPDATE_ON_BOOT=1). Before
 * 2026-10-02 the type was only a label: nothing in the platform ever set the
 * variable (docs/MODS-COVERAGE.md), so the Mods tab refused every plugin.
 * `carbon` is deliberately not mapped: the image has no Carbon switch.
 * Unverified on a live server (no real provision possible from the build
 * session) — see docs/DOCUMENTATION.md, "Growth batch G5".
 */
export const RUST_OXIDE_ENV = { RUST_OXIDE_ENABLED: "1", RUST_OXIDE_UPDATE_ON_BOOT: "1" } as const;

export function applyGameVariant(setupScript: string, family: string | null, variant: string | null): string {
  if (family === "rust") {
    if (variant !== "oxide") return setupScript;
    if (/-e\s+RUST_OXIDE_ENABLED=/.test(setupScript)) return setupScript;
    const flags = Object.entries(RUST_OXIDE_ENV).map(([k, v]) => `-e ${k}=${v}`).join(" ");
    return setupScript.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 ${flags}`);
  }
  if (family !== "minecraft") return setupScript;
  if (!variant) return setupScript;
  if (/-e\s+TYPE=/.test(setupScript)) return setupScript;
  const type = variant.toUpperCase();
  return setupScript.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e TYPE=${type}`);
}

/**
 * Substitute the Minecraft image's Java-runtime tag to match the customer's
 * checkout-time VERSION choice.
 *
 * FOUND LIVE 2026-09-20: unlike every other customizable field, the
 * `itzg/minecraft-server` IMAGE TAG in `prisma/catalog.ts`'s setupScript is
 * not a `-e KEY=...` docker env var — it's the image reference itself — so
 * `applyGameConfigEnv` below (which only ever rewrites `-e KEY=` placeholders)
 * never touched it. Every Minecraft server was provisioned on the catalog's
 * static `:java21` regardless of the VERSION actually picked at checkout,
 * silently crash-looping any version needing a different Java (26.1+ needs
 * Java 25 — see lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS for the real,
 * researched mapping and the live incident that found this).
 *
 * Deliberately minecraft-only and deliberately narrow: touches ONLY the
 * `itzg/minecraft-server(:tag)?` image reference, nothing else in the script.
 * Falls back to the schema's own VERSION default when the customer's
 * `gameConfig` doesn't carry one (an order that never touched the field) —
 * matching today's catalog default (1.21.1 -> java21) exactly, so a customer
 * who never touches VERSION sees no change in behavior.
 */
export function applyMinecraftJavaImage(
  setupScript: string,
  family: string | null,
  gameConfig: Record<string, unknown> | null | undefined
): string {
  if (family !== "minecraft") return setupScript;
  if (!/itzg\/minecraft-server(:[\w.-]+)?/.test(setupScript)) return setupScript;
  const version = gameConfig && gameConfig["VERSION"] != null ? String(gameConfig["VERSION"]) : "1.21.1";
  const image = minecraftImageForVersion(version);
  return setupScript.replace(/itzg\/minecraft-server(:[\w.-]+)?/, image);
}

/**
 * The generalization this file's own docstring called for: substitute a
 * customer's checkout-time `Server.gameConfig` values into an OsTemplate's
 * setupScript, for whichever fields already appear in it as a docker
 * `-e KEY=...` env-var placeholder.
 *
 * Found live 2026-08-31 auditing DST (`dst` family): the whole per-family
 * customization schema in lib/game-config.ts (`ConfigField`, one per
 * `docker run -e KEY=...` in prisma/seed-wave4-games.ts and its Wave 1-3
 * predecessors) is captured at checkout into `Server.gameConfig`
 * (lib/game-order.ts) and shown in the post-deploy Settings tab, but — same
 * root cause as `applyGameVariant` above, just never generalized —
 * `provision()` in worker/index.ts never read it. Every family's setup
 * script always ran with its hardcoded static default (usually `''`),
 * regardless of what the customer entered at checkout. For most fields that
 * meant a cosmetically-wrong default (wrong MOTD, wrong hostname string);
 * for DST's `TOKEN` (an online DST cluster refuses to start with none — see
 * lib/game-config.ts's DST schema comment) it meant the container never
 * bound its port at all and PROVISION's own `checkGamePortOpen` health check
 * would time out and hard-fail the customer's paid order.

  return out;
}

/**
 * If a GAME OsTemplate's setupScript installs the game via a detached
 * `docker run -d --name <container> ...` (true for every game image today —
 * see the OsTemplate rows for minecraft/terraria/ark/etc., all `docker run -d`),
 * rewrite the invocation to `docker create` and append a generated systemd unit
 * that starts/stops the container. Also caps the container's log driver
 * (`--log-opt max-size=10m --log-opt max-file=3`) — see the comment at the
 * `createCmd` line below for why.
 *
 * WHY THIS EXISTS: the whole game control panel — GAME_POWER start/stop/restart,
 * GAME_BACKUP, log tailing (lib/game-control.ts + worker/game-control.ts) —
 * resolves the running game exclusively via `systemctl cat <serviceHint>` /
 * `journalctl -u <unit>`. A bare `docker run -d` creates no systemd unit at all,
 * so every one of those lookups comes back empty and every control action fails
 * silently, on every game family, on every order. Found 2026-08-26 diagnosing a
 * customer's Terraria server (cmt9ss7ln000xhlrx0gch9fcx) that could never be
 * started/stopped from the dashboard even though PROVISION had completed
 * successfully — the container was in fact running, just entirely invisible to
 * systemd.
 *
 * The generated unit is named after the family's FIRST serviceHint, not the
 * docker container's own `--name` — the two don't always match (minecraft's
 * image runs as container "mc" but its control-spec hints are "minecraft" /
 * "minecraft-server") — so `systemctl cat <hint>` resolves regardless of what an
 * individual image's setup script happened to call its container.
 *
 * Intentionally conservative: any setupScript that doesn't match the exact
 * `docker run -d --name X ...` shape (or any non-game family, e.g. the
 * LAMP/WordPress/Caddy panel images that already install a real native systemd
 * service) is returned completely unchanged.
 *
 * Moved here from worker/index.ts 2026-09-24 (alongside `buildGameSetupScript`
 * below) so worker/game-control.ts — which worker/index.ts itself imports, so
 * it cannot import anything back from worker/index.ts without a circular
 * dependency — can also build a real reinstall script for the Danger Zone's
 * wipe/reinstall action. Purely a relocation: behavior is unchanged.
 */
export function wrapDockerGameService(setupScript: string, family: string | null): string {
  if (!isGameFamily(family)) return setupScript;
  const unitName = controlSpec(family)?.serviceHints[0];
  if (!unitName) return setupScript;

  const re = /docker run\s+(?:-d|--detach)\b(.*?)\s+--name[= ]("?)([A-Za-z0-9_.-]+)\2(.*)$/.exec(setupScript.trim());
  if (!re) return setupScript;
  const [full, before, , containerName, after] = re;
  const matchIndex = setupScript.indexOf(full);
  if (matchIndex < 0) return setupScript;

  // Strip docker's own restart policy — systemd now owns restart semantics for
  // this container, and leaving both in place makes the two supervisors fight
  // over a crash-looping process.
  const cleanedAfter = after.replace(/\s*--restart(?:=|\s+)\S+/, "");
  // Cap the container's json-file log driver. No game image's setupScript ever
  // set this, so a crash-looping container (systemd restarting it every 5s
  // forever — see RestartSec above) grows an unbounded log file. Root-caused
  // live 2026-09-17 on projectzomboid-kc0kcr: its docker json log alone had
  // grown to ~28 GB (on top of ~28.5 GB of rsyslog spamming its own
  // "no space left on device" write failures once the disk filled), filling
  // the 77 GB root disk to 100% and taking the game server down. This is the
  // single construction point every game family's `docker run` is rewritten
  // through, so applying the cap here covers all of them at once rather than
  // editing each family's setupScript individually. 10m x 3 files = a 30 MB
  // ceiling per container regardless of how long or how hard it crash-loops.
  const createCmd = `docker create --name ${containerName} --log-opt max-size=10m --log-opt max-file=3${before}${cleanedAfter}`
    .replace(/\s+/g, " ")
    .trim();

  const prefix = setupScript.slice(0, matchIndex);
  // FIRST-BOOT RELIABILITY (2026-10-02, docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md):
  // the container used to be created by ONE `docker create` whose implicit image
  // pull had no retry. valheim-gjjrv9's pull died ~50 s in, the script carried
  // on, installed the unit, and valheim.service restarted 85 times against "No
  // such container" while nothing anywhere tried the pull again. Now:
  //   - the create (and so the pull) is retried with backoff inside the guest;
  //     layers that finished downloading are kept by dockerd, so a retry resumes;
  //   - it is idempotent: a container already built from THIS exact command is
  //     kept, one built from a different command (an earlier attempt with a
  //     broken config, e.g. a blank ADMIN_USERNAME) is replaced — so a re-run
  //     re-applies a corrected config instead of repeating the broken start;
  //   - progress/failure is written to /var/lib/nxeon/game-setup.state, which
  //     the worker polls with short SSH reads (lib/provision-guard.ts
  //     startupProbeCommand) instead of guessing from the outside.
  const cfgHash = createHash("sha256").update(createCmd).digest("hex").slice(0, 16);
  const header = [
    "mkdir -p /var/lib/nxeon",
    `nx_state() { echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) $*" >> /var/lib/nxeon/game-setup.state; }`,
    // One setup run at a time (cloud-init's and a worker re-run can overlap on
    // a slow first boot): the second waits, then finds the container present.
    "exec 9>/var/lib/nxeon/game-setup.lock; flock -w 1800 9 || true",
    "echo $$ > /var/lib/nxeon/game-setup.pid",
    "trap 'rm -f /var/lib/nxeon/game-setup.pid' EXIT",
    `nx_state "setup started"`,
    "nx_create_cmd() {",
    createCmd,
    "}",
    "nx_game_create() {",
    `  if docker container inspect ${containerName} >/dev/null 2>&1 && [ "$(cat /var/lib/nxeon/game-container.cfg 2>/dev/null)" = "${cfgHash}" ]; then nx_state "container present"; return 0; fi`,
    `  docker rm -f ${containerName} >/dev/null 2>&1 || true`,
    "  nx_n=0",
    "  while :; do",
    "    nx_n=$((nx_n+1))",
    `    nx_state "creating container (attempt $nx_n of ${CREATE_ATTEMPTS})"`,
    `    if nx_create_cmd; then echo "${cfgHash}" > /var/lib/nxeon/game-container.cfg; nx_state "container created"; return 0; fi`,
    `    if [ "$nx_n" -ge ${CREATE_ATTEMPTS} ]; then nx_state "failed: docker create (image pull) failed ${CREATE_ATTEMPTS} times"; return 1; fi`,
    "    sleep $((nx_n*15))",
    "  done",
    "}",
  ].join("\n");
  const unit = [
    `cat > /etc/systemd/system/${unitName}.service <<'NXUNIT'`,
    "[Unit]",
    `Description=Nxeon game service (docker: ${containerName})`,
    "After=docker.service",
    "Requires=docker.service",
    // Never let the start rate limit refuse a customer's own Start/Restart;
    // hammering is bounded by the restart backoff below instead.
    "StartLimitIntervalSec=0",
    "",
    "[Service]",
    `ExecStart=/usr/bin/docker start -a ${containerName}`,
    `ExecStop=/usr/bin/docker stop -t 30 ${containerName}`,
    "Restart=always",
    "RestartSec=5",
    // systemd >= 254 (Ubuntu 24.04 ships 255): back off 5s -> 120s across
    // consecutive automatic restarts, so a game that exits on start (PZ with a
    // blank admin username, 40 restarts in 20 min) stops hammering the node.
    // Older systemd ignores both keys with a warning.
    "RestartSteps=5",
    "RestartMaxDelaySec=120",
    "TimeoutStartSec=0",
    "",
    "[Install]",
    "WantedBy=multi-user.target",
    "NXUNIT",
    "systemctl daemon-reload",
    `systemctl enable --now ${unitName}`,
    // Keep the script's exit status = the enable's (GAME_REINSTALL reads it).
    `nx_rc=$?; if docker container inspect ${containerName} >/dev/null 2>&1; then nx_state "ready"; else nx_state "failed: no container after setup"; fi; (exit $nx_rc)`,
  ].join("\n");

  return `${header}\n${prefix}nx_game_create || { tail -n 1 /var/lib/nxeon/game-setup.state 2>/dev/null | grep -q failed || nx_state "failed: setup step before the container (see /var/log/nxeon-setup.log)"; }\n${unit}`;
}

/** In-guest `docker create` (= image pull) attempts before the setup gives up; the worker can re-run it after. */
export const CREATE_ATTEMPTS = 6;

/**
 * Skip the Docker CE install when Docker is already on the guest.
 *
 * Every game setupScript starts `curl -fsSL https://get.docker.com | sh && …`.
 * On a stock image that is the install (measured 2026-10-01 on node-5: ~25s
 * including the image pull). On a GOLDEN template (scripts/golden/) Docker is
 * baked in, and on a GAME_REINSTALL the guest already has it — re-running
 * get.docker.com there costs an apt update + a package reinstall (and may
 * restart dockerd) for nothing. Same exit-status semantics: the group
 * succeeds if Docker exists or the install succeeded.
 */
export function skipDockerInstallIfPresent(setupScript: string): string {
  return setupScript.replace(
    /curl -fsSL https:\/\/get\.docker\.com \| sh(?=\s*&&)/,
    // Retried (2026-10-02): one transient failure of get.docker.com used to
    // fail the whole game install with nothing ever re-trying it.
    "{ command -v docker >/dev/null 2>&1 || { for nx_i in 1 2 3; do curl -fsSL https://get.docker.com | sh && break; sleep 10; done; command -v docker >/dev/null 2>&1; }; }"
  );
}

/**
 * Optional Docker registry mirror / pull-through cache for game image pulls
 * (`NXEON_DOCKER_REGISTRY_MIRROR=https://mirror.example:5000`). Unset = no
 * change at all. Only written on a guest that has no Docker yet and no
 * daemon.json, so dockerd reads it on its first start and nothing needs a
 * restart. A mirror that is down costs nothing: dockerd falls back to the
 * upstream registry. See docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md
 * ("registry mirror") for the design and why it matters on non-primary nodes
 * (every VM behind one NAT IP shares one anonymous Docker Hub pull budget).
 */
export function registryMirrorPrelude(mirror: string | null | undefined): string | null {
  const m = (mirror ?? "").trim();
  if (!m) return null;
  if (!/^https?:\/\/[A-Za-z0-9.-]{1,253}(?::\d{1,5})?\/?$/.test(m)) return null;
  return (
    `command -v docker >/dev/null 2>&1 || [ -e /etc/docker/daemon.json ] || ` +
    `{ mkdir -p /etc/docker && printf '{"registry-mirrors":["%s"]}\\n' '${m}' > /etc/docker/daemon.json; }`
  );
}

/**
 * Minecraft JVM heap vs the VM's RAM.
 *
 * FOUND 2026-10-01: the catalog hardcodes `-e MEMORY=2G`, and itzg sets BOTH
 * -Xms and -Xmx from it, so on the 2 GB plan the JVM tries to commit the
 * entire VM's RAM as heap before the OS, dockerd and the JVM's own non-heap
 * memory get anything. Reproduced on a clean 2 GB VM with no swap: "There is
 * insufficient memory for the Java Runtime Environment to continue … failed to
 * map 2147483648 bytes", crash loop, NRestarts=78 in 10 minutes. A real order
 * only starts because every VM gets a RAM-sized swapfile — i.e. part of the
 * heap lives in swap. The opposite on the 8 GB plan: still a 2G heap, so the
 * customer paid for 8 GB and Minecraft could use 2.
 *
 * Rule: leave max(768 MB, 25%) of the VM for the OS + dockerd + JVM non-heap,
 * round down to 256 MB, never below 512 MB. A customer's explicit choice is
 * honoured but clamped to that ceiling; no choice (or the schema default "2G")
 * means "size it to my plan".
 */
export function minecraftMaxHeapMB(ramMB: number): number {
  const headroom = Math.max(768, Math.round(ramMB * 0.25));
  return Math.max(512, Math.floor((ramMB - headroom) / 256) * 256);
}

/** Parse an itzg MEMORY value ("2G", "1536M", "1024m") into MB; null if unparseable. */
export function parseHeapMB(value: unknown): number | null {
  const m = /^\s*(\d+(?:\.\d+)?)\s*([GgMm])\s*$/.exec(String(value ?? ""));
  if (!m) return null;
  const n = Number(m[1]);
  return Math.round(m[2].toLowerCase() === "g" ? n * 1024 : n);
}

